318	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
319	        refuseClosed(sheetId, claim.getDueBy());
320	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimStatusChangeException();
321	        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
322	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
323	                .orElseThrow(PersonNotFoundException::new);
324	        claim.setStatus(ClaimStatus.DELETED);
325	        claim.unlock();
326	        claims.flush();
327	        log(user, person, claim);
328	        record("CLAIM_DELETED", user, person, claim, claim.getNumber());
329	        return claim;
330	    }
331	
332	    /** Restore a DELETED claim: it is a DRAFT again. Refused unless the claim is DELETED, when the sheet's
333	     * today is not the day it was deleted (its status log's last DELETED date), and when its due-by is in
334	     * a closed period. */
335	    @Transactional
336	    public Claim restore(String sheetId, String user, long claimId) {
337	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
338	        refuseClosed(sheetId, claim.getDueBy());
339	        if (claim.getStatus() != ClaimStatus.DELETED) throw new ClaimStatusChangeException();
340	        LocalDate deleted = logs.findByClaimIdInOrderByIdAsc(List.of(claim.getId())).stream()
341	                .filter(entry -> entry.getStatus() == ClaimStatus.DELETED)
342	                .map(ClaimLog::getDate)
343	                .reduce((first, second) -> second)
344	                .orElse(null);
345	        if (!sheets.today(sheetId).equals(deleted)) throw new ClaimRestoreLateException();
346	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
347	                .orElseThrow(PersonNotFoundException::new);
348	        claim.setStatus(ClaimStatus.DRAFT);
349	        claims.flush();
350	        log(user, person, claim);
351	        record("CLAIM_RESTORED", user, person, claim, claim.getNumber());
352	        return claim;
353	    }
354	
355	    /** Defer an OPEN claim until {@code until}, a date after the sheet's today: until the sheet's today
356	     * reaches it the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
357	     * statement. Refused unless the claim is OPEN, when {@code until} is not after the sheet's today, and
358	     * when the claim is dated in a closed period. */
359	    @Transactional
360	    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
361	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
362	        refuseClosed(sheetId, claim.getDueBy());
363	        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusChangeException();
364	        if (!until.isAfter(sheets.today(sheetId))) throw new ClaimDeferException();
365	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
366	                .orElseThrow(PersonNotFoundException::new);
367	        RollupService.Snapshot before = rollup.snapshot(sheetId);
368	        claim.setDeferredUntil(until);
369	        claims.flush();
370	        record("CLAIM_DEFERRED", user, person, claim, claim.getNumber(), "until=" + until);
371	        rollup.recordSince(sheetId, user, before);
372	        return claim;
373	    }
374	
375	    /** Remind an OPEN or PENDING claim: a reminder is written and the claim is reminded on the sheet's
376	     * today. Refused unless the claim is OPEN or PENDING, when it was already reminded on the sheet's
377	     * today, and when its due-by is in a closed period. */
378	    @Transactional
379	    public Claim remind(String sheetId, String user, long claimId) {
380	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
381	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
382	            throw new ClaimStatusChangeException();
383	        }
384	        LocalDate today = sheets.today(sheetId);
385	        if (today.equals(claim.getRemindedOn())) throw new ClaimRemindedException();
386	        refuseClosed(sheetId, claim.getDueBy());
387	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
388	                .orElseThrow(PersonNotFoundException::new);
389	        claim.setRemindedOn(today);
390	        claims.flush();
391	        record("REMIND", user, person, claim, claim.getNumber());
392	        return claim;
393	    }
394	
395	    /** A steward's re-date of an OPEN or PENDING claim to {@code date}. Its due-by stays as it was fixed,
396	     * so its period and number stay too, and a figure a statement bound it to stays bound. Refused when the
397	     * user is not a steward, unless the claim is OPEN or PENDING, when its due-by is in a closed period,
398	     * and when the new date is after its person's retirement date. */
399	    @Transactional
400	    public Claim redate(String sheetId, String user, long claimId, LocalDate date) {
401	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
402	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
403	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
404	            throw new ClaimStatusChangeException();
405	        }
406	        refuseClosed(sheetId, claim.getDueBy());
407	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
408	                .orElseThrow(PersonNotFoundException::new);
409	        person.requireClaimable(date);
410	        RollupService.Snapshot before = rollup.snapshot(sheetId);
411	        LocalDate old = claim.getDate();
412	        claim.setDate(date);
413	        claims.flush();
414	        record("CLAIM_REDATED", user, person, claim, claim.getNumber(), "old=" + old, "new=" + date);
415	        rollup.recordSince(sheetId, user, before);
416	        return claim;
417	    }
418	
419	    /** Split {@code amount} (more than 0.00 and less than the claim's amount) off an OPEN claim: the
420	     * claim keeps the rest and loses any figure a statement bound it to; a new OPEN claim of the split-off
421	     * amount, with the same person, date and note, is given the next number, is opened by the user, has
422	     * its due-by fixed now from the terms in force on its date and names the claim's number as the one
423	     * it was split from; it is a late entry when that due-by falls in a soft-closed period. Refused unless
424	     * the claim is OPEN and not deferred on the sheet's today, and when its due-by or the new claim's falls
425	     * in a closed period. Both claims are returned, the original first. */
426	    @Transactional
427	    public List<Claim> split(String sheetId, String user, long claimId, BigDecimal amount) {
428	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
429	        refuseClosed(sheetId, claim.getDueBy());
430	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
431	            throw new ClaimStatusChangeException();
432	        }
433	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) throw new ClaimSplitException();
434	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
435	                .orElseThrow(PersonNotFoundException::new);
436	        RollupService.Snapshot before = rollup.snapshot(sheetId);
437	        claim.setAmount(claim.getAmount().subtract(amount));
438	        claim.unbind();
439	        Claim split = new Claim(sheetId, person.getId(), amount, claim.getDate(), claim.getNote(), null);
440	        int terms = termsOf(sheetId, person, claim.getDate());
441	        split.fixTerms(claim.getDate(), terms);
442	        split.setDueBy(holidays.dueBy(sheetId, claim.getDate(), terms));
443	        refuseClosed(sheetId, split.getDueBy());
444	        split.setLateEntry(periods.softClosedOn(sheetId, split.getDueBy()));
445	        split.setListed(sheets.nextInSequence(sheetId, "listed"));
446	        split.setStatus(ClaimStatus.OPEN);
447	        split.setNumber(nextNumber(sheetId, split.getDueBy()));
448	        split.setOpenedBy(user);
449	        split.setSplitFrom(claim.getNumber());
450	        split.setTags(claim.getTags().isEmpty() ? null : String.join(",", claim.getTags()));
451	        split = claims.saveAndFlush(split);
452	        log(user, person, split);
453	        record("CLAIM_SPLIT", user, person, claim, claim.getNumber(), "into=" + split.getNumber());
454	        record("CLAIM_OPENED", user, person, split, split.getNumber());
455	        rollup.recordSince(sheetId, user, before);
456	        return List.of(claim, split);
457	    }
458	
459	    /** A steward's approval of a PENDING claim: it becomes SETTLED, fixing what is due on it then (its
460	     * live figure, which no statement binds while it is PENDING, together with its late charge then).
461	     * Refused unless the claim is PENDING, when the user is not a steward or opened or last edited the claim, and when it
462	     * has no proofs and that due is above the proof threshold in force on its date. */
463	    @Transactional
464	    public Claim approve(String sheetId, String user, long claimId) {
465	        Claim claim = lockPending(sheetId, user, claimId);
466	        if (claim.isOpenedOrEditedBy(user)) throw new ClaimNotStewardException();
467	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
468	                .orElseThrow(PersonNotFoundException::new);
469	        RollupService.Snapshot before = rollup.snapshot(sheetId);
470	        BigDecimal figure = rollup.dueOf(claim, person);
471	        BigDecimal due = rollup.liveDueOf(claim, figure);
472	        refuseUnproved(claim, person, due);
473	        claim.setSettledDue(due);
474	        claim.setStatus(ClaimStatus.SETTLED);
475	        claims.flush();
476	        log(user, person, claim);
477	        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), "due=" + dueText(due));
478	        notifyWatchers(user, person, claim);
479	        rollup.recordSince(sheetId, user, before);
480	        return claim;
481	    }
482	
483	    /** Raise the claim's proofs count by one. Refused when the claim is SETTLED or VOID; a proof leaves
484	     * the claim's figures alone, so it may be added while the claim is dated in a closed period. */
485	    @Transactional
486	    public Claim addProof(String sheetId, String user, long claimId) {
487	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
488	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
489	                || claim.getStatus() == ClaimStatus.DELETED) {
490	            throw new ClaimStatusChangeException();
491	        }
492	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
493	                .orElseThrow(PersonNotFoundException::new);
494	        claim.addProof();
495	        claims.flush();
496	        record("CLAIM_PROOF_ADDED", user, person, claim, claim.getNumber(), "proofs=" + claim.getProofs());
497	        return claim;
498	    }
499	
500	    /** A steward's rejection of a PENDING claim, for {@code reason}: it goes back to OPEN, bound again
501	     * by its person's last statement if that statement included it. Refused unless the claim is
502	     * PENDING, and when the user is not a steward. */
503	    @Transactional
504	    public Claim reject(String sheetId, String user, long claimId, String reason) {
505	        Claim claim = lockPending(sheetId, user, claimId);
506	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
507	                .orElseThrow(PersonNotFoundException::new);
508	        RollupService.Snapshot before = rollup.snapshot(sheetId);
509	        claim.setStatus(ClaimStatus.OPEN);
510	        claims.flush();
511	        log(user, person, claim);
512	        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), "reason=" + reason);
513	        rollup.recordSince(sheetId, user, before);
514	        return claim;
515	    }
516	
517	    /** A move, by a role the permission matrix allows to reassign (a steward by default), of a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
518	     * date but, unless a draft (which has no number), is given the next number in the sequence it is
519	     * numbered in (as when opened now), its old number never used again; it loses
520	     * any figure a statement bound it to (it is live again until its new person's next statement), and is listed as its new person's newest claim. Refused when the user's
521	     * role may not reassign, when the claim is SETTLED or VOID, is a correction (it corrects a claim of its
522	     * own person) or already belongs to the person, when it is dated or due by in a closed period, and when it
523	     * is dated after the new person's retirement date. */
524	    @Transactional
525	    public Claim reassign(String sheetId, String user, long claimId, long personId) {
526	        return move(sheetId, user, claimId, personId, false);
527	    }
528	
529	    /** A move of one of several claims moved together: by the rules of {@link #reassign}, except that a
530	     * claim that already belongs to the person goes through (it is listed as the person's newest claim,
531	     * and recorded). */
532	    @Transactional
533	    public Claim reassignOfBulk(String sheetId, String user, long claimId, long personId) {
534	        return move(sheetId, user, claimId, personId, true);
535	    }
536	
537	    private Claim move(String sheetId, String user, long claimId, long personId, boolean samePerson) {
538	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
539	        if (!settings.allowed(sheetId, user, Action.REASSIGN)) throw new ClaimNotStewardException();
540	        refuseClosed(sheetId, claim.getDueBy());
541	        refuseClosed(sheetId, claim.getDate());
542	        ClaimStatus status = claim.getStatus();
543	        if ((status != ClaimStatus.DRAFT && status != ClaimStatus.OPEN && status != ClaimStatus.PENDING)
544	                || claim.isCorrection() || (!samePerson && claim.getPersonId() == personId)) {
545	            throw new ClaimReassignException();
546	        }
547	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
548	                .orElseThrow(PersonNotFoundException::new);
549	        Person to = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
550	        to.requireClaimable(claim.getDate());
551	        RollupService.Snapshot before = rollup.snapshot(sheetId);
552	        claim.setPersonId(to.getId());
553	        claim.unbind();
554	        if (claim.getNumber() != null) claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
555	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
556	        claims.flush();
557	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(), "from=" + from.getName(), "to=" + to.getName());
558	        rollup.recordSince(sheetId, user, before);
559	        return claim;
560	    }
561	
562	    /** A steward's re-settle of a SETTLED claim: it is fixed again at what would be due on it now were
563	     * it OPEN and bound by no statement (its person's rate and grade, the sheet's floor and its late
564	     * charge, all as they are now). Refused unless the claim is SETTLED, when the user is not a
565	     * steward, and when it is dated in a closed period. */
566	    @Transactional
567	    public Claim resettle(String sheetId, String user, long claimId) {
568	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
569	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
570	        refuseClosed(sheetId, claim.getDueBy());
571	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusChangeException();
572	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
573	                .orElseThrow(PersonNotFoundException::new);
574	        RollupService.Snapshot before = rollup.snapshot(sheetId);
575	        BigDecimal old = claim.getSettledDue();
576	        BigDecimal due = rollup.openShownOf(claim, person);
577	        claim.setSettledDue(due);
578	        claims.flush();
579	        log(user, person, claim);
580	        record("CLAIM_RESETTLED", user, person, claim, claim.getNumber(), "old=" + dueText(old), "new=" + dueText(due));
581	        notifyWatchers(user, person, claim);
582	        rollup.recordSince(sheetId, user, before);
583	        return claim;
584	    }
585	
586	    /** Refuse a void of the SETTLED claim unless the user is a steward and the sheet's today is at most
587	     * 7 days after the date its status log first shows it SETTLED. */
588	    private void refuseLateVoid(String sheetId, String user, Claim claim) {
589	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
590	        LocalDate settled = logs.findByClaimIdInOrderByIdAsc(List.of(claim.getId())).stream()
591	                .filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
592	                .map(ClaimLog::getDate)
593	                .findFirst()
594	                .orElseThrow(ClaimStatusChangeException::new);
595	        if (sheets.today(sheetId).isAfter(settled.plusDays(7))) throw new ClaimVoidLateException();
596	    }
597	
598	    /** The PENDING claim, locked, for a steward to approve or reject. */
599	    private Claim lockPending(String sheetId, String user, long claimId) {
600	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
601	        refuseClosed(sheetId, claim.getDueBy());
602	        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusChangeException();
603	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
604	        return claim;
605	    }
606	
607	    private static String dueText(BigDecimal due) {
608	        return due == null ? "n/a" : due.toPlainString();
609	    }
610	
611	    /** The figure the claim shows and totals now, without its late charge or floor; null when it has no figure
612	     * (see {@link RollupService#figureOf}). */
613	    public BigDecimal figureOf(Claim claim, Person person) {
614	        return rollup.figureOf(claim, person);
615	    }
616	
617	    /** What is due on the claim as it shows and totals now, its late charge included; null when it has
618	     * no figure (see {@link RollupService#shownOf}). */
619	    public BigDecimal shownOf(Claim claim, Person person) {
620	        return rollup.shownOf(claim, person);
621	    }
622	
623	    /** Keep each of the claim's tags among those ever used on its sheet. */
624	    public void keepTags(Claim claim) {
625	        for (String tag : claim.getTags()) {
626	            SheetTag.Key key = new SheetTag.Key(claim.getSheetId(), tag);
627	            if (!tagRepository.existsById(key)) tagRepository.save(new SheetTag(claim.getSheetId(), tag));
628	        }
629	    }
630	
631	    /** Write the status the claim has now to its log, with the sheet's today and what is due on it as
632	     * it shows now. */
633	    private void log(String user, Person person, Claim claim) {
634	        logs.save(new ClaimLog(claim.getId(), claim.getStatus(), user, sheets.today(claim.getSheetId()),
635	                rollup.shownOf(claim, person)));
636	    }
637	
638	    /** Record a change to the claim; {@code number}, the number it has (or had), follows when there is one,
639	     * then any {@code extra} fields. */
640	    private void record(String event, String user, Person person, Claim claim, String number, String... extra) {
641	        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
642	                "amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
643	                "date=" + claim.getDate()));
644	        if (number != null) fields.add("number=" + number);
645	        fields.addAll(List.of(extra));
646	        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
647	    }
648	
649	    /** Notify each user watching the person, in the order they started watching, that the claim was
650	     * settled, approved or re-settled. */
651	    private void notifyWatchers(String user, Person person, Claim claim) {
652	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
653	            audit.change("NOTIFY", claim.getSheetId(), user, "user=" + watch.getUser(), "person=" + person.getName(),
654	                    "number=" + claim.getNumber());
655	        }
656	    }
657	
658	    /** The number a claim due by {@code date} is given when opened now: within the period containing
659	     * that date ({@code <period name>-<n>}, or {@code X-<n>} when none does) while the sheet numbers by
660	     * period, otherwise the next sheet-wide number. */
661	    public String nextNumber(String sheetId, LocalDate date) {
662	        if (!sheets.numbersByPeriod(sheetId)) return String.valueOf(sheets.nextClaimNumber(sheetId));
663	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
664	                .filter(p -> !date.isBefore(p.getFrom()) && !date.isAfter(p.getTo()))
665	                .findFirst()
666	                .map(p -> p.getName() + "-" + sheets.nextInSequence(sheetId, "period:" + p.getId()))
667	                .orElseGet(() -> "X-" + sheets.nextInSequence(sheetId, "none"));
668	    }
669	
670	    /** Whether a settle by {@code user} of a claim whose due is {@code due} needs a steward's approval:
671	     * the user is a clerk and the due is above the sheet's clerk limit. */
672	    private boolean overLimit(String sheetId, String user, BigDecimal due) {
673	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
674	        BigDecimal limit = settings.clerkLimit(sheetId);
675	        return limit != null && due.compareTo(limit) > 0;
676	    }
677	
678	    /** Refuse a settle or approval of the claim, whose due is {@code due}, while it has no proofs and that
679	     * due is above the proof threshold in force on its date: its person's grade's own then, else the sheet's
680	     * (a due that is n/a is within any threshold). */
681	    private void refuseUnproved(Claim claim, Person person, BigDecimal due) {
682	        if (due == null || claim.getProofs() > 0) return;
683	        BigDecimal threshold = settings.proofThresholdFor(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
684	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimProofRequiredException();
685	    }
686	
687	    /** Refuse an open of the claim, whose due is {@code due}, while its note is empty and that due is
688	     * above the note threshold in force on its date (a due that is n/a is within any threshold). */
689	    private void refuseNoteless(Claim claim, BigDecimal due) {
690	        if (due == null || !noteOf(claim.getNote()).isEmpty()) return;
691	        BigDecimal threshold = settings.noteThresholdOn(claim.getSheetId(), claim.getDate());
692	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimNoteRequiredException();
693	    }
694	
695	    /** Refuse a correction (a negative {@code amount}) that does not name, by number, a SETTLED claim of
696	     * the person, and a claim that names one without being a correction. */
697	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
698	        if (amount.signum() >= 0) {
699	            if (corrects != null) throw new ClaimCorrectionException();
700	            return;
701	        }
702	        if (corrects == null) throw new ClaimCorrectionException();
703	        claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
704	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
705	                .orElseThrow(ClaimCorrectionException::new);
706	    }
707	
708	    /** Refuse the external reference {@code ref} when a claim on the sheet other than {@code claimId} has
709	     * it, compared without regard to case. */
710	    private void refuseRefTaken(String sheetId, Long claimId, String ref) {
711	        if (ref == null) return;
712	        claims.findBySheetIdAndRefKey(sheetId, Claim.keyOf(ref))
713	                .filter(other -> !other.getId().equals(claimId))
714	                .ifPresent(other -> {
715	                    throw new ClaimRefTakenException();
716	                });
717	    }
718	
719	    /** Refuse a change to a claim due by {@code date} when a closed period of the sheet contains it. */
720	    private void refuseClosed(String sheetId, LocalDate date) {
721	        if (periods.closedOn(sheetId, date)) throw new ClaimPeriodClosedException();
722	    }
723	
724	    private static String noteOf(String note) {
725	        return note == null ? "" : note.trim();
726	    }
727	
728	    /** The terms a claim of the person dated {@code date} is due by: the person's own terms, else those
729	     * of their grade in force on that date, else the sheet's then. */
730	    private int termsOf(String sheetId, Person person, LocalDate date) {
731	        return person.getTerms() != null ? person.getTerms() : settings.termsFor(sheetId, person.gradeOn(date), date);
732	    }
733	}
