   *  is dated in a closed period. */
  addProof(sheet: string, id: number): Promise<Claim> {
    return firstValueFrom(
      this.http.post<Claim>(`${this.url(sheet)}/claims/${id}/proof`, null, {
        headers: this.session.headers(),
      }),
    );
  }

